-- 0053: the returns / delivery scenario catalogue (generated by supabase/seed/gen_scenarios.py).
-- Reference data behind Accounting > Scenario Map. Read-only for everyone who can sign in.
create table if not exists logistics_scenarios (
  scenario_code text primary key,
  group_code    text not null,
  group_title   text not null,
  sort_order    int  not null,
  title         text not null,
  what_happens  text,
  stock_effect  text,
  accounting    text,
  gst_note      text,
  claim_note    text,
  app_support   text not null check (app_support in ('auto','partial','tracked','manual','gap')),
  app_note      text,
  rule_codes    text[] not null default '{}'
);
alter table logistics_scenarios enable row level security;
drop policy if exists "scenarios readable" on logistics_scenarios;
create policy "scenarios readable" on logistics_scenarios for select to authenticated using (true);
revoke all on logistics_scenarios from anon;
revoke insert, update, delete on logistics_scenarios from authenticated;

do $seed$
declare d jsonb := $j${"groups":[{"id":"A","title":"Forward delivery (warehouse to customer)","desc":"Everything that can happen between dispatch and a happy customer."},{"id":"B","title":"RTO - return to origin (undelivered)","desc":"The parcel never reached the customer and comes back to us."},{"id":"C","title":"Customer returns (reverse pickup)","desc":"The customer received the parcel and sends it back."},{"id":"D","title":"Exchanges and replacements","desc":"Customer wants a different size/colour, or we owe a replacement."},{"id":"E","title":"Cash on delivery (COD)","desc":"Cash collected by the courier and remitted to us later."},{"id":"F","title":"Marketplace settlements and fees","desc":"Amazon / Flipkart / gateway payouts, fees and deductions."},{"id":"G","title":"Claims and disputes","desc":"Getting money back from couriers, marketplaces and suppliers."},{"id":"H","title":"GST, valuation and period-end","desc":"What the CA cares about when the books are closed."},{"id":"I","title":"Warehouse and stock","desc":"What physically happens to the goods that come back."}],"scenarios":[{"code":"A01","grp":"A","title":"Delivered on first attempt - prepaid","what":"Courier delivers, customer has already paid online (UPI / card / wallet).","stock":"Stock leaves the warehouse at dispatch.","acct":"Invoice at dispatch: Dr Trade Receivables, Cr Sales, Cr GST. Money arrives later in the marketplace / gateway settlement (Dr Bank, Cr Trade Receivables).","gst":"Output GST at the invoice; CGST+SGST within Gujarat, IGST outside.","claim":"-","support":"auto","note":"Settlement receipt is rule-driven (STL-RECEIPT).","rules":["STL-RECEIPT"],"ord":0},{"code":"A02","grp":"A","title":"Delivered on first attempt - COD","what":"Courier hands over the parcel and collects cash.","stock":"Stock leaves at dispatch.","acct":"Invoice at dispatch (Dr Trade Receivables). When the courier collects: Dr COD Receivable from Couriers, Cr Trade Receivables. When the courier remits: Dr Bank, Cr COD Receivable.","gst":"Same as A01.","claim":"-","support":"auto","note":"","rules":["COD-COLLECTED","COD-REMITTED"],"ord":1},{"code":"A03","grp":"A","title":"Delivery delayed beyond the promised date","what":"Weather, strikes, festival rush, hub congestion. Customer may cancel or the marketplace may penalise a late delivery.","stock":"No change - goods are with the courier.","acct":"No entry until there is an effect (cancellation -> A20, penalty -> bank/settlement deduction, compensation -> claim).","gst":"-","claim":"Possible: late-delivery penalty reversal on marketplaces.","support":"gap","note":"No promised-date / SLA tracking in the app. Recommend adding expected_delivery_date to orders and an 'overdue in transit' list.","rules":["BNK-PENALTY"],"ord":2},{"code":"A04","grp":"A","title":"Attempt failed - customer not available","what":"Door locked / phone not answered. Courier re-attempts (usually up to 3 times over 3-5 days).","stock":"No change.","acct":"No entry.","gst":"-","claim":"-","support":"tracked","note":"Order stays 'shipped'. Courier webhook can raise an RTO when attempts are exhausted.","rules":[],"ord":3},{"code":"A05","grp":"A","title":"Attempt failed - address wrong or incomplete","what":"Missing landmark, wrong pincode, unreachable building. Courier raises an NDR (non-delivery report) and waits 48-72 h for the seller to fix it.","stock":"No change.","acct":"No entry. If not fixed in time the courier starts an RTO (see B01).","gst":"-","claim":"-","support":"gap","note":"No NDR queue in the app. Recommend an 'Action needed' list fed by the courier webhook so someone calls the customer before the parcel turns around.","rules":[],"ord":4},{"code":"A06","grp":"A","title":"Customer asks to reschedule or change delivery slot","what":"Customer travelling / wants a weekend delivery.","stock":"No change.","acct":"No entry.","gst":"-","claim":"-","support":"tracked","note":"Courier-side action.","rules":[],"ord":5},{"code":"A07","grp":"A","title":"Customer refuses at the door","what":"Changed mind, found it cheaper, did not order, parcel opened and rejected.","stock":"Goods go back to the courier - RTO starts.","acct":"See B01 / B03 - sale reversed when goods are received back.","gst":"See B03.","claim":"No.","support":"auto","note":"Treated as an RTO with reason 'Customer refused'.","rules":["RTO-REV-COD","RTO-REV-PREPAID-D2C","RTO-REV-OTHER"],"ord":6},{"code":"A08","grp":"A","title":"COD customer does not have the cash","what":"Customer is home but cannot pay.","stock":"Becomes an RTO.","acct":"See B11.","gst":"See B03.","claim":"No.","support":"auto","note":"Common on COD orders. Consider prepaid-only for risky pincodes.","rules":["RTO-REV-COD"],"ord":7},{"code":"A09","grp":"A","title":"Pincode not serviceable / out-of-delivery-area surcharge","what":"Courier accepted the booking but cannot deliver, or charges an ODA surcharge.","stock":"Becomes an RTO if undeliverable.","acct":"RTO as B01. ODA surcharge arrives as a freight bill (bank rule BNK-COURIER).","gst":"Freight GST 18% as ITC.","claim":"Maybe: surcharge dispute.","support":"auto","note":"","rules":["BNK-COURIER"],"ord":8},{"code":"A10","grp":"A","title":"Parcel stuck or misrouted at a hub","what":"No tracking movement for days; sorted to the wrong city.","stock":"No change.","acct":"No entry unless it becomes lost (A11).","gst":"-","claim":"Becomes a lost-shipment claim after the courier's no-movement limit (usually 15 days).","support":"tracked","note":"","rules":[],"ord":9},{"code":"A11","grp":"A","title":"Parcel lost in transit","what":"Courier declares it lost. Customer gets a refund or replacement.","stock":"Stock is gone - it will never be received back.","acct":"Log as an RTO and mark it Claimed: sale reversed by credit note (RTO-REV-*). With the Inventory pack on, cost moves from COGS to Damaged & Lost Stock Loss. Raise a lost_shipment claim; recognise Dr Claims Receivable / Cr Claim Recoveries only when approved.","gst":"Credit note reverses output GST. ITC on the lost goods is reversed under Sec 17(5)(h) if the loss is not recovered.","claim":"Yes - lost_shipment claim against the courier (limit is usually declared value, capped).","support":"auto","note":"Add the claim from the Claims screen straight away so the deadline clock is tracked.","rules":["RTO-REV-COD","RTO-REV-PREPAID-D2C","RTO-REV-OTHER","INV-WRITEOFF-RTO","CLM-APPROVED","CLM-RECOVERED"],"ord":10},{"code":"A12","grp":"A","title":"Parcel damaged in transit","what":"Torn bag, water damage, crushed box. Customer refuses it or accepts and returns it.","stock":"Damaged goods come back (RTO) or are returned (C-group).","acct":"Credit note as RTO / return. Inspect as 'damaged' -> Claimed. Claim against the courier.","gst":"Credit note reverses GST.","claim":"Yes - damaged_return claim.","support":"auto","note":"Photos at unboxing are what win these claims.","rules":["RTO-REV-COD","RET-CN-D2C","RET-CN-MKT","INV-WRITEOFF-RTO","INV-WRITEOFF-RETURN"],"ord":11},{"code":"A13","grp":"A","title":"Partial delivery - one box of a multi-box order missing","what":"Order shipped in two cartons, one arrives.","stock":"Part of the stock is with the customer, part is missing.","acct":"Needs a partial credit note for the missing part.","gst":"Credit note for the missing value only.","claim":"Yes - lost_shipment for the missing carton.","support":"gap","note":"The app reverses whole invoices only. Recommend line-level returns/credit notes (see C20).","rules":[],"ord":12},{"code":"A14","grp":"A","title":"Order split across two warehouses","what":"Surat has some SKUs, the Mumbai 3PL has the rest.","stock":"Each warehouse is reduced separately.","acct":"One invoice, two stock movements.","gst":"Place of supply is unchanged.","claim":"-","support":"gap","note":"Orders ship from one warehouse today. Recommend per-line warehouse on order lines.","rules":[],"ord":13},{"code":"A15","grp":"A","title":"Wrong item dispatched (our mistake)","what":"Picker sent the wrong size / colour / style.","stock":"Wrong item comes back, right item goes out.","acct":"Return with reason 'Wrong item received' (credit note + restock), then a fresh replacement order. No claim - this is our own cost.","gst":"Credit note + new invoice.","claim":"No (seller error).","support":"auto","note":"Track picking accuracy separately - it is a process leak, not a courier problem.","rules":["RET-CN-D2C","RET-CN-MKT"],"ord":14},{"code":"A16","grp":"A","title":"Short quantity or missing accessory","what":"Combo set missing a piece, dupatta not in the packet.","stock":"Customer keeps most of it.","acct":"Partial refund -> manual credit note, or full return.","gst":"Credit note for the difference.","claim":"Sometimes (if packed correctly and courier tampered).","support":"manual","note":"Partial credit notes are manual today (C19).","rules":[],"ord":15},{"code":"A17","grp":"A","title":"Customer says 'not received' but tracking shows delivered","what":"Fake claim, wrong-person delivery, neighbour/security accepted it.","stock":"Goods are with the customer (or lost).","acct":"If we are forced to refund: marketplace chargeback / A-to-Z deduction shows in settlement or bank (BNK-PENALTY, review) and is disputed with proof of delivery.","gst":"No reversal of the invoice unless we accept the refund.","claim":"Yes - dispute with POD / OTP / photo evidence.","support":"manual","note":"","rules":["BNK-PENALTY"],"ord":16},{"code":"A18","grp":"A","title":"Customer cancels before dispatch","what":"Order is paid but cancelled before an invoice exists.","stock":"Reserved stock is released.","acct":"No sales entry (no invoice yet). Prepaid refund goes back via the gateway; the gateway fee is not refunded - it stays an expense (BNK-GATEWAY).","gst":"None.","claim":"No.","support":"tracked","note":"The cancel hook only fires when an invoice exists, so cheap pre-dispatch cancellations do not create noise.","rules":["BNK-GATEWAY"],"ord":17},{"code":"A19","grp":"A","title":"Seller cancels (out of stock, price error, fraud suspicion)","what":"We cannot fulfil. Marketplaces charge a cancellation penalty to the seller.","stock":"Reserved stock is released.","acct":"No sales entry. Marketplace penalty: Dr Marketplace Penalties & Chargebacks (review).","gst":"No GST on a penalty.","claim":"Dispute if the cancellation was not ours.","support":"auto","note":"","rules":["BNK-PENALTY"],"ord":18},{"code":"A20","grp":"A","title":"Cancelled after dispatch (intercept)","what":"Customer or seller asks the courier to stop and return the parcel.","stock":"Goods come back as an RTO.","acct":"As B01-B03. Both-way freight is a cost (BNK-COURIER, BNK-RTO-CHARGES).","gst":"Credit note on receipt.","claim":"No.","support":"auto","note":"","rules":["RTO-REV-COD","RTO-REV-PREPAID-D2C","RTO-REV-OTHER","BNK-RTO-CHARGES"],"ord":19},{"code":"A21","grp":"A","title":"Cancelled after invoicing, before the courier picks up","what":"Invoice exists but the goods never left.","stock":"Stock returns to available.","acct":"Order marked Cancelled -> credit note posts automatically (own store prepaid: Cr Customer Refunds Payable; otherwise Cr Trade Receivables).","gst":"Credit note reverses GST.","claim":"No.","support":"auto","note":"Order must have an invoice for the hook to fire.","rules":["ORD-CANCEL-D2C-PREPAID","ORD-CANCEL-OTHER"],"ord":20},{"code":"A22","grp":"A","title":"Fake / prank / duplicate order","what":"Typical on COD: wrong phone number, someone else's address, same order placed twice.","stock":"Becomes an RTO.","acct":"As B11. The cost is the two-way freight plus packaging.","gst":"Credit note on receipt.","claim":"No.","support":"gap","note":"No risk scoring. Recommend a per-pincode and per-customer RTO rate on the Insights screen to push risky COD orders to prepaid.","rules":["RTO-REV-COD"],"ord":21},{"code":"A23","grp":"A","title":"Delivered to the wrong person","what":"Neighbour / watchman / wrong flat.","stock":"Goods are with someone else.","acct":"Treat like A17 and file a lost-shipment claim if the courier agrees it was mis-delivered.","gst":"-","claim":"Yes.","support":"manual","note":"","rules":[],"ord":22},{"code":"B01","grp":"B","title":"RTO initiated by the courier","what":"Three failed attempts, refusal, wrong address left unfixed, or seller instruction.","stock":"Goods are travelling back (RTO in transit). Not in any warehouse yet.","acct":"No entry yet - the sale is only reversed when the goods are physically received back.","gst":"Output GST stays until the credit note.","claim":"-","support":"tracked","note":"Courier webhook creates the RTO as 'initiated' / 'in transit'. Your CA may prefer reversing at initiation; the hook fires on receipt - change the event if policy differs.","rules":[],"ord":23},{"code":"B02","grp":"B","title":"RTO in transit (4-10 days)","what":"Reverse leg of the journey; same delays and loss risks as the forward leg.","stock":"In transit.","acct":"No entry.","gst":"-","claim":"Lost on the way back -> B07.","support":"tracked","note":"","rules":[],"ord":24},{"code":"B03","grp":"B","title":"RTO received - parcel intact, goods resaleable","what":"Seal intact, tags intact, quantities match.","stock":"Restocked into the chosen warehouse. With the Inventory pack: Dr Inventory, Cr COGS.","acct":"Credit note posts automatically: Dr Sales Returns & RTO Reversals, Dr CGST/SGST or IGST, Cr Trade Receivables (COD / marketplace) or Cr Customer Refunds Payable (own-store prepaid).","gst":"Credit note mirrors the invoice's GST split. Appears in the GST summary credit notes.","claim":"No.","support":"auto","note":"A second event (inspected, restocked) never double-posts.","rules":["RTO-REV-COD","RTO-REV-PREPAID-D2C","RTO-REV-OTHER","INV-RTO-RESTOCK"],"ord":25},{"code":"B04","grp":"B","title":"RTO received - damaged by the courier","what":"Torn, crushed, wet, tampered.","stock":"Quarantined; not available to sell.","acct":"Credit note as B03. Inspection 'damaged' -> Claimed. With the Inventory pack: cost moves from COGS to Damaged & Lost Stock Loss. Claim approved -> Dr Claims Receivable, Cr Claim Recoveries.","gst":"Credit note reverses GST. Claim recovery is not a supply (no GST).","claim":"Yes - damaged_return against the courier.","support":"auto","note":"","rules":["RTO-REV-COD","RTO-REV-PREPAID-D2C","RTO-REV-OTHER","INV-WRITEOFF-RTO","CLM-APPROVED","CLM-RECOVERED"],"ord":26},{"code":"B05","grp":"B","title":"RTO received - different item inside (swapped)","what":"Customer or someone en route swapped the garment for a cheap one.","stock":"Wrong item quarantined.","acct":"As B04, inspection 'wrong_item'. Evidence: unboxing video, weight at dispatch vs receipt.","gst":"As B04.","claim":"Yes - against the courier or (marketplaces) SAFE-T / SPF.","support":"auto","note":"","rules":["INV-WRITEOFF-RTO","CLM-APPROVED"],"ord":27},{"code":"B06","grp":"B","title":"RTO received - used, washed, tag removed","what":"Worn once and refused.","stock":"Quarantined -> may be resold as B-grade.","acct":"Credit note as B03. Stock is held in quarantine (no write-off by default). If sold as B-grade at a discount, the difference is a loss.","gst":"As B03.","claim":"Sometimes.","support":"auto","note":"Quarantine is not written off automatically because it may be resold - change the rule condition if your policy differs.","rules":["RTO-REV-COD","RTO-REV-OTHER"],"ord":28},{"code":"B07","grp":"B","title":"RTO never arrives (lost on the way back)","what":"Courier shows RTO delivered / lost but the warehouse never receives it.","stock":"Stock is gone.","acct":"Mark RTO Claimed -> credit note + write-off + lost_shipment claim, as A11.","gst":"As A11.","claim":"Yes - lost_shipment.","support":"auto","note":"","rules":["INV-WRITEOFF-RTO","CLM-APPROVED"],"ord":29},{"code":"B08","grp":"B","title":"RTO received after the month (or year) was closed","what":"Parcel arrives weeks later.","stock":"Restocked when it arrives.","acct":"Credit note is dated the day it is processed, in the current OPEN period - closed periods are never reopened.","gst":"Sec 34(2): credit notes must be issued by 30 November after the financial year-end or the annual return date, whichever is earlier, or the output-tax reduction is lost.","claim":"-","support":"auto","note":"If the date falls in a closed period the event is logged as an error for the accountant, never silently dropped.","rules":[],"ord":30},{"code":"B09","grp":"B","title":"RTO of a prepaid own-store order","what":"Customer paid on Shopify, parcel returned.","stock":"As B03.","acct":"Credit note creates Customer Refunds Payable. Pay the refund from the bank and record it (refund rule: Dr Customer Refunds Payable, Cr Bank).","gst":"As B03.","claim":"-","support":"partial","note":"There is no refund screen for RTOs (only for customer returns). Recommend adding a 'Mark refunded' action on the RTO page.","rules":["RTO-REV-PREPAID-D2C","RET-REFUND-D2C"],"ord":31},{"code":"B10","grp":"B","title":"RTO of a prepaid marketplace order","what":"Marketplace refunds the customer and adjusts our payout.","stock":"As B03.","acct":"Credit note reduces Trade Receivables (what the marketplace owes us). No bank entry - the marketplace nets it in a settlement.","gst":"As B03.","claim":"-","support":"auto","note":"","rules":["RTO-REV-OTHER"],"ord":32},{"code":"B11","grp":"B","title":"RTO of a COD order","what":"No cash was ever collected.","stock":"As B03.","acct":"Credit note reduces Trade Receivables (nothing was collected from the customer). The real cost is freight both ways + the COD handling fee.","gst":"As B03.","claim":"No.","support":"auto","note":"","rules":["RTO-REV-COD","BNK-RTO-CHARGES"],"ord":33},{"code":"B12","grp":"B","title":"RTO charges and COD fees","what":"Forward freight + reverse freight + COD fee are non-refundable. Marketplaces show an 'RTO fee' inside settlements.","stock":"-","acct":"Courier bills paid from the bank: Dr Reverse Logistics & RTO Charges, Dr ITC (18%), Cr Bank. Settlement deductions are currently booked as one commission expense.","gst":"18% GST on courier services is input credit.","claim":"Dispute wrong charges.","support":"partial","note":"Courier bills: automatic. Settlement fees are lumped together - recommend splitting by fee_type (commission / shipping / RTO / gateway) into separate expense ledgers.","rules":["BNK-RTO-CHARGES","BNK-COURIER"],"ord":34},{"code":"B13","grp":"B","title":"Chronic RTO pincodes and customers","what":"30-40% RTO in some regions on COD.","stock":"-","acct":"-","gst":"-","claim":"-","support":"gap","note":"Recommend RTO rate by pincode / courier / SKU on the Business Insights screen.","rules":[],"ord":35},{"code":"B14","grp":"B","title":"Courier re-attempts after RTO was initiated","what":"Customer calls and accepts delivery after all.","stock":"Back to forward delivery.","acct":"No entry (nothing was posted at initiation).","gst":"-","claim":"-","support":"gap","note":"An RTO cannot be cancelled in the app. Recommend a 'Cancel RTO / re-attempt' action.","rules":[],"ord":36},{"code":"C01","grp":"C","title":"Return policy and window","what":"7 / 10 / 15 / 30 day windows; non-returnable items (innerwear, altered or customised pieces, sarees with falls attached).","stock":"-","acct":"No entry.","gst":"-","claim":"-","support":"gap","note":"The app does not enforce a return window or category rules. Recommend a window per category and a warning on late return requests.","rules":[],"ord":37},{"code":"C02","grp":"C","title":"Return requested -> approved -> pickup scheduled","what":"Customer raises it, support approves, courier pickup is booked.","stock":"Goods still with the customer.","acct":"No entry.","gst":"-","claim":"-","support":"tracked","note":"Statuses: Requested, Approved, Pickup, In transit.","rules":[],"ord":38},{"code":"C03","grp":"C","title":"Pickup fails - customer not ready / not available","what":"Reverse pickup attempts fail up to 3 times; request auto-closes.","stock":"No change.","acct":"No entry. Reverse pickup fee may still be billed (BNK-RTO-CHARGES).","gst":"-","claim":"-","support":"tracked","note":"","rules":["BNK-RTO-CHARGES"],"ord":39},{"code":"C04","grp":"C","title":"Customer self-ships the return","what":"Remote area without pickup; customer sends it by post/courier and is reimbursed.","stock":"Goods arrive at the warehouse.","acct":"Reimbursement: Dr Reverse Logistics & RTO Charges, Cr Bank.","gst":"GST only if the customer provides a valid invoice (rare).","claim":"-","support":"manual","note":"","rules":["BNK-RTO-CHARGES"],"ord":40},{"code":"C05","grp":"C","title":"Reason: size / fit","what":"Top reason in garments (30-40% of returns). Wrong size ordered or the brand runs small/large.","stock":"Restock if tags intact.","acct":"Credit note (C13). Consider an exchange (D01) rather than a refund to keep the sale.","gst":"As C13.","claim":"No.","support":"auto","note":"Track fit-returns by SKU and size to fix the size chart.","rules":["RET-CN-D2C","RET-CN-MKT"],"ord":41},{"code":"C06","grp":"C","title":"Reason: colour / look different from the photo","what":"Fabric shade differs on screen vs in hand.","stock":"Restock if tags intact.","acct":"Credit note (C13).","gst":"As C13.","claim":"No.","support":"auto","note":"","rules":["RET-CN-D2C","RET-CN-MKT"],"ord":42},{"code":"C07","grp":"C","title":"Reason: quality / stitching / fabric defect","what":"Seams open, colour bleeds, fabric thin - seller-side problem.","stock":"Quarantine; not resold as new.","acct":"Credit note (C13). Inspection 'damaged' -> Claimed with the Inventory pack: cost moves to Damaged & Lost Stock Loss. Supplier / karigar debit note is manual.","gst":"As C13.","claim":"Supplier recovery (not a courier claim).","support":"partial","note":"No supplier debit-note flow. Recommend a defect register by supplier / production lot.","rules":["RET-CN-D2C","RET-CN-MKT","INV-WRITEOFF-RETURN"],"ord":43},{"code":"C08","grp":"C","title":"Reason: damaged on arrival","what":"Transit damage reported on delivery.","stock":"Quarantine.","acct":"Credit note + write-off + damaged_return claim against the courier.","gst":"As C13.","claim":"Yes - courier.","support":"auto","note":"","rules":["RET-CN-D2C","RET-CN-MKT","INV-WRITEOFF-RETURN","CLM-APPROVED"],"ord":44},{"code":"C09","grp":"C","title":"Reason: wrong item received","what":"See A15 - our picking error.","stock":"Restock the returned item.","acct":"Credit note + replacement (D03).","gst":"As C13.","claim":"No.","support":"auto","note":"","rules":["RET-CN-D2C","RET-CN-MKT"],"ord":45},{"code":"C10","grp":"C","title":"Reason: changed mind / found cheaper / not needed","what":"No fault anywhere.","stock":"Restock if unused.","acct":"Credit note (C13). Some marketplaces charge the customer a fee instead.","gst":"As C13.","claim":"No.","support":"auto","note":"","rules":["RET-CN-D2C","RET-CN-MKT"],"ord":46},{"code":"C11","grp":"C","title":"Reason: delivered too late","what":"Event or festival has passed.","stock":"Restock if unused.","acct":"Credit note (C13).","gst":"As C13.","claim":"Maybe: late-delivery compensation from the courier.","support":"auto","note":"","rules":["RET-CN-D2C","RET-CN-MKT"],"ord":47},{"code":"C12","grp":"C","title":"Reason: missing piece in a set / combo","what":"Kurta set without the dupatta.","stock":"Restock what comes back.","acct":"Full return (C13) or partial credit note (C19).","gst":"As C13.","claim":"Maybe.","support":"partial","note":"","rules":["RET-CN-D2C"],"ord":48},{"code":"C13","grp":"C","title":"Return received - good condition","what":"Tags intact, unwashed, as sent.","stock":"Restocked into the chosen warehouse. With the Inventory pack: Dr Inventory, Cr COGS at cost.","acct":"Credit note posts automatically: Dr Sales Returns, Dr GST (same split as the invoice), Cr Customer Refunds Payable (own store) or Cr Trade Receivables (marketplace).","gst":"Appears in the GST summary under credit notes; reduces output tax in the month it is issued.","claim":"No.","support":"auto","note":"","rules":["RET-CN-D2C","RET-CN-MKT","RET-CN-OTHER","INV-RETURN-RESTOCK"],"ord":49},{"code":"C14","grp":"C","title":"Return received - worn, washed, stained, perfume smell, tags removed","what":"'Wardrobing' - worn once and returned.","stock":"Quarantined; may be resold as B-grade.","acct":"Options: reject the refund (C18) or accept with a deduction (C19). Default: credit note + quarantine.","gst":"As C13.","claim":"Sometimes.","support":"partial","note":"Deduction-based partial refunds are manual (C19).","rules":["RET-CN-D2C","RET-CN-MKT"],"ord":50},{"code":"C15","grp":"C","title":"Return received - a different item sent back","what":"Customer sends back a cheaper garment, or a brick in the box.","stock":"Wrong item quarantined.","acct":"Refund should be withheld / reversed. Marketplace: SAFE-T / SPF claim. Inspection 'wrong_item' -> Claimed.","gst":"Credit note only if the refund is finally granted.","claim":"Yes - marketplace protection claim.","support":"partial","note":"","rules":["INV-WRITEOFF-RETURN","CLM-APPROVED"],"ord":51},{"code":"C16","grp":"C","title":"Return received - empty box / missing items","what":"Parcel arrived light.","stock":"Nothing to restock.","acct":"As C15, inspection 'missing'.","gst":"As C15.","claim":"Yes - courier (tampering) or marketplace.","support":"partial","note":"","rules":["CLM-APPROVED"],"ord":52},{"code":"C17","grp":"C","title":"Return received - damaged","what":"Torn or soiled beyond normal use.","stock":"Quarantined / written off.","acct":"Credit note (if refund granted) + write-off with the Inventory pack. Claim if the damage happened in transit.","gst":"As C13.","claim":"Sometimes.","support":"auto","note":"","rules":["RET-CN-D2C","RET-CN-MKT","INV-WRITEOFF-RETURN"],"ord":53},{"code":"C18","grp":"C","title":"Return rejected at inspection","what":"Does not meet the return policy (outside window, used, no tags).","stock":"Returned to the customer (RTC).","acct":"No credit note, no revenue reversal. Refund status Rejected. Outbound freight 