y, Cr COGS. D: Dr Damaged & Lost Stock Loss.","gst":"-","claim":"-","support":"partial","note":"The app has good / damaged / wrong_item / missing + restocked / quarantined / claimed. Recommend a grade field.","rules":["INV-RETURN-RESTOCK","INV-WRITEOFF-RETURN"],"ord":104},{"code":"I03","grp":"I","title":"Restock into which warehouse","what":"Own warehouse vs the nearest 3PL.","stock":"Goes to the selected warehouse.","acct":"No entry (same company).","gst":"Stock transfer between GSTINs would need a delivery challan.","claim":"-","support":"tracked","note":"Warehouse is chosen when dispositioning.","rules":[],"ord":105},{"code":"I04","grp":"I","title":"Quarantine bin","what":"Held for inspection, repair or claim evidence.","stock":"Not counted as available stock.","acct":"No entry unless it is written off.","gst":"-","claim":"-","support":"tracked","note":"Only restocked goods enter the sellable balance.","rules":[],"ord":106},{"code":"I05","grp":"I","title":"Cycle-count differences","what":"Count differs from the system.","stock":"Adjusted up or down.","acct":"Shortage: Dr Damaged & Lost Stock Loss, Cr Inventory. Excess: reverse.","gst":"ITC reversal on shortage (H03).","claim":"-","support":"auto","note":"Inventory pack.","rules":["INV-ADJ-LOSS","INV-ADJ-GAIN"],"ord":107},{"code":"I06","grp":"I","title":"Return with an unmapped SKU","what":"Product on the order line has no SKU mapping.","stock":"Not restocked - the app warns.","acct":"No inventory movement, so no COGS entry.","gst":"-","claim":"-","support":"tracked","note":"Map the SKU, then restock manually.","rules":[],"ord":108},{"code":"I07","grp":"I","title":"Aged returned stock (seasonal garments)","what":"Returned winterwear in March loses value.","stock":"Sits in stock.","acct":"Write-down (H04).","gst":"-","claim":"-","support":"tracked","note":"Per-SKU stock time-out highlights these on the Inventory screen.","rules":[],"ord":109}]}$j$::jsonb; g jsonb; x jsonb;
begin
  delete from logistics_scenarios;
  for x in select * from jsonb_array_elements(d -> 'scenarios') loop
    select y into g from jsonb_array_elements(d -> 'groups') y where y ->> 'id' = x ->> 'grp';
    insert into logistics_scenarios (scenario_code, group_code, group_title, sort_order, title, what_happens, stock_effect, accounting, gst_note, claim_note, app_support, app_note, rule_codes)
    values (x ->> 'code', x ->> 'grp', g ->> 'title', (x ->> 'ord')::int, x ->> 'title', x ->> 'what', x ->> 'stock', x ->> 'acct', x ->> 'gst', x ->> 'claim',
            x ->> 'support', nullif(x ->> 'note', ''), coalesce(array(select jsonb_array_elements_text(x -> 'rules')), '{}'));
  end loop;
end
$seed$;
